package com.loja.checkout;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication
public class CheckoutApplication {
    public static void main(String[] args) {
        SpringApplication.run(CheckoutApplication.class, args);
    }
}

package com.loja.checkout.api;

import java.math.BigDecimal;
import java.util.List;

public record ResumoRequest(
    List<Item> itens,
    String modalidadeEntrega,
    String cupom,
    String formaPagamento,
    Integer parcelas,
    String nivelClube,
    String regiao
) {
    public record Item(String nome, BigDecimal precoUnitario, Integer quantidade, BigDecimal pesoKg) {}
}

package com.loja.checkout.api;

import java.math.BigDecimal;

public record ResumoResponse(
    BigDecimal subtotalProdutos,
    BigDecimal descontoCupom,
    BigDecimal frete,
    int prazoEntregaDias,
    BigDecimal seguro,
    BigDecimal ajustePagamento,
    BigDecimal totalFinal,
    int parcelas,
    BigDecimal valorParcela,
    BigDecimal creditoProximaCompra,
    boolean brinde
) {}

package com.loja.checkout.api;

import com.loja.checkout.erro.CheckoutException;
import com.loja.checkout.servico.CheckoutServico;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.Map;

@RestController
@RequestMapping("/checkout")
public class CheckoutController {

    private final CheckoutServico checkoutServico;

    public CheckoutController(CheckoutServico checkoutServico) {
        this.checkoutServico = checkoutServico;
    }

    @PostMapping("/resumo")
    public ResponseEntity<ResumoResponse> resumo(@RequestBody ResumoRequest request) {
        ResumoResponse resumo = checkoutServico.calcular(request);
        return ResponseEntity.ok(resumo);
    }

    @ExceptionHandler(CheckoutException.class)
    public ResponseEntity<Map<String, String>> handleCheckoutException(CheckoutException ex) {
        return ResponseEntity.unprocessableEntity()
                .body(Map.of("erro", ex.getErro().name()));
    }
}

package com.loja.checkout.erro;

public class CheckoutException extends RuntimeException {
    private final ErroCheckout erro;

    public CheckoutException(ErroCheckout erro) {
        super(erro.name());
        this.erro = erro;
    }

    public ErroCheckout getErro() {
        return erro;
    }
}

package com.loja.checkout.dominio.entrega;

import java.math.BigDecimal;

public interface ModalidadeEntrega {
    BigDecimal calcularFrete(BigDecimal pesoKgTotal);
    int prazoEntregaDias();
    boolean estaDisponivel(BigDecimal pesoKgTotal);
}

package com.loja.checkout.dominio.entrega;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class EntregaEconomica implements ModalidadeEntrega {

    @Override
    public BigDecimal calcularFrete(BigDecimal pesoKgTotal) {
        return new BigDecimal("12.00")
                .add(new BigDecimal("2.00").multiply(pesoKgTotal))
                .setScale(2, RoundingMode.HALF_EVEN);
    }

    @Override
    public int prazoEntregaDias() {
        return 7;
    }

    @Override
    public boolean estaDisponivel(BigDecimal pesoKgTotal) {
        return true;
    }
}

package com.loja.checkout.dominio.entrega;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class EntregaExpressa implements ModalidadeEntrega {

    @Override
