        return true;
    }

    @Override
    public BigDecimal calcularDesconto(BigDecimal subtotalProdutos, BigDecimal frete, List<ResumoRequest.Item> itens) {
        BigDecimal total = BigDecimal.ZERO;
        for (ResumoRequest.Item item : itens) {
