1	package com.loja.checkout.servico;
2	
3	import com.loja.checkout.api.ResumoRequest;
4	import com.loja.checkout.api.ResumoResponse;
5	import com.loja.checkout.dominio.NivelClube;
6	import com.loja.checkout.dominio.Regiao;
7	import com.loja.checkout.dominio.cupom.Cupom;
8	import com.loja.checkout.dominio.cupom.Cupons;
9	import com.loja.checkout.dominio.entrega.ModalidadeEntrega;
10	import com.loja.checkout.dominio.entrega.ModalidadesEntrega;
11	import com.loja.checkout.dominio.pagamento.FormaPagamento;
12	import com.loja.checkout.dominio.pagamento.FormasPagamento;
13	import com.loja.checkout.erro.CheckoutException;
14	import com.loja.checkout.erro.ErroCheckout;
15	import org.springframework.stereotype.Service;
16	
17	import java.math.BigDecimal;
18	import java.math.RoundingMode;
19	
20	@Service
21	public class CheckoutServico {
22	
23	    private final ModalidadesEntrega modalidadesEntrega;
24	    private final Cupons cupons;
25	    private final FormasPagamento formasPagamento;
26	
27	    public CheckoutServico(ModalidadesEntrega modalidadesEntrega, Cupons cupons, FormasPagamento formasPagamento) {
28	        this.modalidadesEntrega = modalidadesEntrega;
29	        this.cupons = cupons;
30	        this.formasPagamento = formasPagamento;
31	    }
32	
33	    public ResumoResponse calcular(ResumoRequest request) {
34	        // 1. Validar pedido
35	        if (request.itens() == null || request.itens().isEmpty()) {
36	            throw new CheckoutException(ErroCheckout.PEDIDO_INVALIDO);
37	        }
38	        for (ResumoRequest.Item item : request.itens()) {
39	            if (item.nome() == null
40	                    || item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0
41	                    || item.quantidade() == null || item.quantidade() <= 0
42	                    || item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
43	                throw new CheckoutException(ErroCheckout.PEDIDO_INVALIDO);
44	            }
45	        }
46	
47	        // 2. Calcular subtotal e peso total
48	        BigDecimal subtotalProdutos = BigDecimal.ZERO;
49	        BigDecimal pesoTotal = BigDecimal.ZERO;
50	        for (ResumoRequest.Item item : request.itens()) {
51	            subtotalProdutos = subtotalProdutos.add(
52	                    item.precoUnitario().multiply(new BigDecimal(item.quantidade()))
53	            );
54	            pesoTotal = pesoTotal.add(
55	                    item.pesoKg().multiply(new BigDecimal(item.quantidade()))
56	            );
57	        }
58	        subtotalProdutos = subtotalProdutos.setScale(2, RoundingMode.HALF_EVEN);
59	
60	        // 3. Validar nível do clube
61	        if (request.nivelClube() == null || request.nivelClube().isBlank()) {
62	            throw new CheckoutException(ErroCheckout.NIVEL_CLUBE_INVALIDO);
63	        }
64	        NivelClube nivelClube;
65	        try {
66	            nivelClube = NivelClube.valueOf(request.nivelClube());
67	        } catch (IllegalArgumentException e) {
68	            throw new CheckoutException(ErroCheckout.NIVEL_CLUBE_INVALIDO);
69	        }
70	
71	        // 4. Validar região
72	        if (request.regiao() == null || request.regiao().isBlank()) {
73	            throw new CheckoutException(ErroCheckout.REGIAO_INVALIDA);
74	        }
75	        Regiao regiao;
76	        try {
77	            regiao = Regiao.valueOf(request.regiao());
78	        } catch (IllegalArgumentException e) {
79	            throw new CheckoutException(ErroCheckout.REGIAO_INVALIDA);
80	        }
81	
82	        // 5. Validar modalidade de entrega
83	        if (request.modalidadeEntrega() == null || request.modalidadeEntrega().isBlank()) {
84	            throw new CheckoutException(ErroCheckout.MODALIDADE_INVALIDA);
85	        }
86	        ModalidadeEntrega entrega = modalidadesEntrega.encontrar(request.modalidadeEntrega())
87	                .orElseThrow(() -> new CheckoutException(ErroCheckout.MODALIDADE_INVALIDA));
88	
89	        // 6. Verificar disponibilidade da modalidade
90	        if (!entrega.estaDisponivel(pesoTotal)) {
91	            throw new CheckoutException(ErroCheckout.MODALIDADE_INDISPONIVEL);
92	        }
93	
94	        // 7. Calcular frete
95	        BigDecimal freteBase = entrega.calcularFrete(pesoTotal);
96	        BigDecimal frete = nivelClube.isFreteGratis()
97	                ? BigDecimal.ZERO.setScale(2)
98	                : freteBase;
99	
100	        // 8 & 9. Processar cupom
101	        BigDecimal descontoCupom;
102	        if (request.cupom() == null || request.cupom().isBlank()) {
103	            descontoCupom = new BigDecimal("0.00");
104	        } else {
105	            Cupom cupom = cupons.encontrar(request.cupom())
106	                    .orElseThrow(() -> new CheckoutException(ErroCheckout.CUPOM_INVALIDO));
107	            if (!cupom.eAplicavel(subtotalProdutos)) {
108	                throw new CheckoutException(ErroCheckout.CUPOM_NAO_APLICAVEL);
109	            }
110	            descontoCupom = cupom.calcularDesconto(subtotalProdutos, frete, request.itens());
111	        }
112	
113	        // 10. Calcular seguro
114	        BigDecimal seguro = regiao.calcularSeguro(subtotalProdutos);
115	
116	        // 11. Calcular total do pedido
117	        BigDecimal totalPedido = subtotalProdutos
118	                .subtract(descontoCupom)
119	                .add(frete)
120	                .add(seguro)
121	                .setScale(2, RoundingMode.HALF_EVEN);
122	
123	        // 12. Número de parcelas
124	        int numParcelas = request.parcelas() != null ? request.parcelas() : 1;
125	
126	        // 13. Validar forma de pagamento
127	        if (request.formaPagamento() == null || request.formaPagamento().isBlank()) {
128	            throw new CheckoutException(ErroCheckout.FORMA_PAGAMENTO_INVALIDA);
129	        }
130	        FormaPagamento pagamento = formasPagamento.encontrar(request.formaPagamento())
131	                .orElseThrow(() -> new CheckoutException(ErroCheckout.FORMA_PAGAMENTO_INVALIDA));
132	
133	        // 14. Validar parcelamento
134	        if (!pagamento.isParcelasValidas(numParcelas)) {
135	            throw new CheckoutException(ErroCheckout.PARCELAMENTO_INVALIDO);
136	        }
137	
138	        // 15. Verificar disponibilidade da forma de pagamento
139	        if (!pagamento.estaDisponivel(totalPedido)) {
140	            throw new CheckoutException(ErroCheckout.FORMA_PAGAMENTO_INDISPONIVEL);
141	        }
142	
143	        // 16. Calcular total final e parcela
144	        BigDecimal totalFinal = pagamento.calcularTotalFinal(totalPedido, numParcelas);
145	        BigDecimal valorParcela = pagamento.calcularValorParcela(totalFinal, numParcelas);
146	        BigDecimal ajustePagamento = totalFinal.subtract(totalPedido);
147	
148	        // 17. Crédito e brinde
149	        BigDecimal credito = nivelClube.calcularCredito(subtotalProdutos);
150	        boolean brinde = nivelClube.isDireitoABrinde(subtotalProdutos);
151	
152	        // 18. Retornar response
153	        return new ResumoResponse(
154	                subtotalProdutos,
155	                descontoCupom,
156	                frete,
157	                entrega.prazoEntregaDias(),
158	                seguro,
159	                ajustePagamento,
160	                totalFinal,
161	                numParcelas,
162	                valorParcela,
163	                credito,
164	                brinde
165	        );
166	    }
167	}
