1	package com.loja.checkout.dominio.pagamento;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	
6	public class PagamentoCartao implements FormaPagamento {
7	
8	    @Override
9	    public boolean isParcelasValidas(int parcelas) {
10	        return parcelas >= 1 && parcelas <= 12;
11	    }
12	
13	    @Override
14	    public boolean estaDisponivel(BigDecimal totalPedido) {
15	        return true;
16	    }
17	
18	    @Override
19	    public BigDecimal calcularTotalFinal(BigDecimal totalPedido, int parcelas) {
20	        if (parcelas <= 3) {
21	            return totalPedido;
22	        }
23	        BigDecimal parcela = calcularParcelaComJuros(totalPedido, parcelas);
24	        return parcela.multiply(new BigDecimal(parcelas));
25	    }
26	
27	    @Override
28	    public BigDecimal calcularValorParcela(BigDecimal totalFinal, int parcelas) {
29	        if (parcelas <= 3) {
30	            return totalFinal.divide(new BigDecimal(parcelas), 2, RoundingMode.HALF_EVEN);
31	        }
32	        // totalFinal = parcela * parcelas, então parcela = totalFinal / parcelas
33	        return totalFinal.divide(new BigDecimal(parcelas), 2, RoundingMode.HALF_EVEN);
34	    }
35	
36	    private BigDecimal calcularParcelaComJuros(BigDecimal totalPedido, int parcelas) {
37	        double taxa = 0.0199;
38	        double fator = Math.pow(1 + taxa, -parcelas);
39	        double denominador = 1.0 - fator;
40	        double parcelaDouble = totalPedido.doubleValue() * taxa / denominador;
41	        return BigDecimal.valueOf(parcelaDouble).setScale(2, RoundingMode.HALF_EVEN);
42	    }
43	}
